 * 결정적 암호화/복호화에 쓰는 고정 키 (secretKey의 SHA-256 앞 16바이트)
 * 입력값마다 키를 바꾸면 복호화할 방법이 없으므로 키는 입력과 무관하게 항상 같아야 한다.
 */
private SecretKeySpec deterministicKey() {
    try {
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        byte[] hash = digest.digest(secretKey.getBytes(StandardCharsets.UTF_8));

        byte[] keyBytes = new byte[16];
        System.arraycopy(hash, 0, keyBytes, 0, 16);

        return new SecretKeySpec(keyBytes, "AES");
    } catch (Exception e) {
        log.error("결정적 키 생성 중 오류 발생: {}", e.getMessage(), e);
        throw new RuntimeException("결정적 키 생성 중 오류가 발생했습니다", e);
    }
}

